if(NS.UI){const set32B=NS.UI.prototype.setWorld,head32B=NS.UI.prototype.renderHeader,content32B=NS.UI.prototype.renderVillageContent;NS.UI.prototype.setWorld=function(w){return set32B.call(this,attach32B(w));};NS.UI.prototype.renderHeader=function(){head32B.call(this);document.title='Village Observer V0.32B';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.32B</strong>';const st=this.q('runtimeStatus');if(st)st.textContent='✓ V0.32B 실제 Person 동원 · 평시 Cohort/Garrison · 민간 노동 이탈';};NS.UI.prototype.renderVillageContent=function(){content32B.call(this);if(this.sub!=='military')return;const v=this.world.selectedNation,root=this.q('villageContent');if(!v||!root)return;const x=summary32B(v,this.world),coh=v.military32A?.cohorts||[],coord=id=>{const t=this.world.map.get(Number(id));return t?`(${t.x},${t.y})`:'-';},level=x.mobilizationLevel32B==='WATCH'?'경계':'평시';root.innerHTML=`<div class="section-head"><div><div class="muted small">V0.32B 실제 Person 동원</div><h2>${v.name} 군사</h2></div><span class="tag">${level}</span></div><div class="grid"><div class="info">동원 가능<div class="big">${x.militaryEligiblePopulation32B}</div></div><div class="info">현역 / 목표<div class="big">${x.activeMilitary32B} / ${x.militaryTargetActive32B}</div></div><div class="info">예비 / 목표<div class="big">${x.reserveMilitary32B} / ${x.militaryTargetReserve32B}</div></div><div class="info">민간 노동 이탈<div class="big">${x.militaryLaborRemoved32B}</div></div><div class="info">Cohort / 주둔지<div class="big">${x.militaryCohorts32B} / ${x.garrisons32B}</div></div><div class="info">전략 경계<div class="big">${x.militaryConcern32B.toFixed(0)}</div></div></div><div class="v32b-note"><strong>🛡️ ${x.militaryDoctrine32B}</strong><div class="small muted">현역은 실제 Person이며 군 복무 중 농업·채굴·건설·유지보수·임금 노동에서 빠집니다. 예비군은 평시에는 민간 직업을 계속 수행합니다.</div><div class="small muted" style="margin-top:5px">누적 군복무로 제거된 민간 노동 ${x.militaryLaborRemovedDays32B.toFixed(0)} person-day · 동원 ${x.militaryMobilizations32B} / 전역 ${x.militaryDemobilizations32B}</div></div>${coh.length?`<div class="v32b-cohorts">${coh.map(c=>{const names=(c.memberIds||[]).map(id=>v.residents.find(p=>String(p.id)===String(id))?.name).filter(Boolean);return`<div class="v32b-cohort"><div><strong>${c.name}</strong><span class="tag">${coord(c.tileId)}</span></div><div class="small">실제 Person ${names.length}명 · 훈련 ${Number(c.training||0).toFixed(0)} · 사기 ${Number(c.morale||0).toFixed(0)} · 보급 ${Number(c.supply||0).toFixed(0)}%</div><div class="small muted">${names.join(' · ')||'구성원 없음'}</div></div>`;}).join('')}</div>`:'<div class="v32b-note small muted">아직 조직된 현역 Cohort가 없습니다. 행정 체계는 예비군을 등록하고, 「봉수와 파수」 기술 이후 평시 주둔군이 활성화됩니다.</div>'}`;};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent='.v32b-note{margin-top:12px;padding:11px;border:1px solid rgba(132,170,255,.28);border-radius:11px;background:rgba(72,112,190,.08)}.v32b-cohorts{display:grid;gap:7px;margin-top:10px}.v32b-cohort{padding:9px 10px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.025)}.v32b-cohort>div:first-child{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:4px}';document.head.appendChild(st);}

